	"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAACAxgD41ghngBmAAQC97rjv+7W/XwAAAABJRU5ErkJg" +
	"gg=="

func mustDecode(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		panic(err)
	}
	return b
}

var (
	iconColor    = mustDecode(iconColorB64)
	iconTemplate = mustDecode(iconTemplateB64)
)
